'use client'

import { useEffect, useState } from 'react'
import { fetchCryptoAssets } from '@/lib/cryptoapi'
import type { CryptoAsset } from '@/types/crypto'
import Pagination from './Pagination'

export default function CryptoList() {
  const [assets, setAssets] = useState<CryptoAsset[]>([])
  const [loading, setLoading] = useState(true)
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(5)

  useEffect(() => {
    setLoading(true)
    fetchCryptoAssets(page)
      .then((data) => {
        setAssets(data)
        setLoading(false)
      })
      .catch(() => setLoading(false))
  }, [page])

  return (
    <div className="overflow-x-auto">
      {loading ? (
        <div className="text-center text-white">Loading...</div>
      ) : (
        <table className="min-w-full table-auto bg-gray-900 text-white border border-gray-700 rounded-lg overflow-hidden">
          <thead className="bg-gray-800 text-sm uppercase text-gray-400">
            <tr>
              <th className="px-4 py-3 text-left">Name</th>
              <th className="px-4 py-3 text-left">Symbol</th>
              <th className="px-4 py-3 text-right">Price (USD)</th>
              <th className="px-4 py-3 text-right">24h Change</th>
              <th className="px-4 py-3 text-right">Market Cap</th>
            </tr>
          </thead>
          <tbody>
            {assets.map((asset) => {
            const price = asset.metrics?.market_data?.price_usd ?? 0
            const change = asset.metrics?.market_data?.percent_change_usd_last_24_hours ?? 0
            const cap = asset.market_cap?.market_cap_usd ?? 0


              return (
                <tr
                  key={asset.id}
                  className="border-t border-gray-700 hover:bg-gray-800 transition"
                >
                  <td className="px-4 py-3">{asset.name}</td>
                  <td className="px-4 py-3 uppercase text-gray-300">{asset.symbol}</td>
                  <td className="px-4 py-3 text-right">${price.toFixed(2)}</td>
                  <td
                    className={`px-4 py-3 text-right ${
                      change >= 0 ? 'text-green-400' : 'text-red-400'
                    }`}
                  >
                    {change.toFixed(2)}%
                  </td>
                  <td className="px-4 py-3 text-right">${(cap / 1_000_000_000).toFixed(2)}B</td>
                </tr>
              )
            })}
          </tbody>
        </table>
      )}

      <div className="mt-6">
        <Pagination currentPage={page} totalPages={totalPages} onPageChange={setPage} />
      </div>
    </div>
  )
}
